// Independent two-body reference for Lambert checks: RK4 with step-doubling
// error control. Deliberately shares no code with orbital.js.
function propagateRK(r0, v0, T, mu, tol = 1e-12) {
  const f = (s) => {
    const rr = Math.hypot(s[0], s[1], s[2]);
    const k = -mu / (rr * rr * rr);
    return [s[3], s[4], s[5], k * s[0], k * s[1], k * s[2]];
  };
  const rk4 = (s, h) => {
    const k1 = f(s);
    const k2 = f(s.map((x, j) => x + 0.5 * h * k1[j]));
    const k3 = f(s.map((x, j) => x + 0.5 * h * k2[j]));
    const k4 = f(s.map((x, j) => x + h * k3[j]));
    return s.map((x, j) => x + (h / 6) * (k1[j] + 2 * k2[j] + 2 * k3[j] + k4[j]));
  };
  let s = [...r0, ...v0];
  let t = 0.0;
  let h = T / 200;
  while (t < T) {
    if (t + h > T) h = T - t;
    const big = rk4(s, h);
    const fine = rk4(rk4(s, 0.5 * h), 0.5 * h);
    const err = vecErr(big.slice(0, 3), fine.slice(0, 3)) / Math.hypot(fine[0], fine[1], fine[2]);
    if (err < tol) {
      s = fine; t += h;
      if (err < tol / 32) h *= 2;
    } else {
      h *= 0.5;
    }
  }
  return s.slice(0, 3);
}

console.log('='.repeat(60));
console.log('CASE 5: Lambert sweep, Earth->Mars-like porkchop grid');
console.log('='.repeat(60));
{
  // Circular Earth (1 AU, ecliptic) and circular Mars (1.5237 AU, 1.85 deg
  // inclined). Departures 0-780 d, TOF 60-500 d covers both Type I and
  // Type II (transfer angle > 180 deg), which the old solver got wrong.
  const mu = 1.32712440018e11, AU = 149597870.7, DAY = 86400.0;
  const rE = AU, rM = 1.5237 * AU, incM = 1.85 / DEG;
  const nE = Math.sqrt(mu / rE ** 3), nM = Math.sqrt(mu / rM ** 3);
  const posE = (t) => [rE * Math.cos(nE * t), rE * Math.sin(nE * t), 0.0];
  const posM = (t) => {
    const th = nM * t + 0.7;
    return [rM * Math.cos(th), rM * Math.sin(th) * Math.cos(incM), rM * Math.sin(th) * Math.sin(incM)];
  };
  let cells = 0, nulls = 0, typeII = 0, worst = 0, worstAt = '';
  for (let dep = 0; dep < 800; dep += 20) {
    for (let tofD = 60; tofD <= 500; tofD += 20) {
      cells++;
      const r1 = posE(dep * DAY), r2 = posM((dep + tofD) * DAY);
      const sol = lambert(r1, r2, tofD * DAY, mu, true);
      if (!sol || !sol.v1.every(Number.isFinite)) { nulls++; continue; }
      if ((r1[0] * r2[1] - r1[1] * r2[0]) < 0) typeII++;
      const err = vecErr(propagateRK(r1, sol.v1, tofD * DAY, mu), r2) / norm(r2);
      if (err > worst) { worst = err; worstAt = `dep ${dep} d, tof ${tofD} d`; }
    }
  }
  console.log(`  cells=${cells}  type II=${typeII}  null=${nulls}`);
  console.log(`  worst endpoint rel err = ${worst.toExponential(3)} (${worstAt})`);
  check('every grid cell solved (no null/NaN)', nulls === 0);
  check('grid includes Type II transfers', typeII > 100);
  check('every solution reaches r2 (<1e-8 relative, independent RK4)', worst < 1e-8);
}

console.log('='.repeat(60));
console.log('CASE 6: Lambert edge cases');
console.log('='.repeat(60));
{
  const mu = 398600.0;
  const r1 = [5000.0, 10000.0, 2100.0];
  const r2 = [-14600.0, 2500.0, 7000.0];
  // Same geometry the long way round (retrograde flag), checked independently.
  const ret = lambert(r1, r2, 3600.0, mu, false);
  const hz = ret ? (r1[0] * ret.v1[1] - r1[1] * ret.v1[0]) : NaN;
  const retErr = ret ? vecErr(propagateRK(r1, ret.v1, 3600.0, mu), r2) / norm(r2) : Infinity;
  console.log(`  retrograde: h_z=${hz.toExponential(3)}  endpoint rel err=${retErr.toExponential(3)}`);
  check('retrograde solution has h_z < 0', hz < 0);
  check('retrograde solution reaches r2 (<1e-8)', retErr < 1e-8);
  // Exactly 180 deg: transfer plane undefined.
  check('180 deg transfer returns null', lambert([7000, 0, 0], [-9000, 0, 0], 5000.0, mu) === null);
  check('zero tof returns null', lambert(r1, r2, 0.0, mu) === null);
  check('negative tof returns null', lambert(r1, r2, -10.0, mu) === null);
  // Very short long-way transfer: must be null or a verified answer, never NaN.
  const fast = lambert(r1, r2, 60.0, mu, false);
  const fastOk = fast === null ||
    vecErr(propagateRK(r1, fast.v1, 60.0, mu), r2) / norm(r2) < 1e-8;
  console.log(`  60 s long-way transfer: ${fast === null ? 'null' : 'solved'}`);
  check('infeasible-looking case is null or verified', fastOk);
}

// Smallest difference between two angles, in radians.
function angDiff(a, b) {
  const d = ((a - b) % (2 * Math.PI) + 3 * Math.PI) % (2 * Math.PI) - Math.PI;
  return Math.abs(d);
}

console.log('='.repeat(60));
console.log(`CASE 7: propagate vs SPICE prop2b_c (${SPICE.meta.toolkit})`);
console.log('='.repeat(60));
{
  // NAIF's prop2b_c is an independent universal-variable propagator.
  const worst = {};
  for (const c of SPICE.twobody) {
    const p = propagate(c.state0.slice(0, 3), c.state0.slice(3), c.dt, c.mu);
    const r1 = c.state1.slice(0, 3);
    const err = vecErr(p.r, r1) / norm(r1);
    const e = Number.isFinite(err) ? err : Infinity;
    worst[c.kind] = Math.max(worst[c.kind] ?? 0, e);
  }
  for (const [kind, w] of Object.entries(worst)) {
    console.log(`  ${kind.padEnd(15)} worst rel pos err = ${w.toExponential(3)}`);
  }
  check('elliptic cases match prop2b_c (<1e-8 relative)', worst.elliptic < 1e-8);
  check('hyperbolic cases match prop2b_c (<1e-8 relative)', worst.hyperbolic < 1e-8);
  // Near-parabolic fixtures (0.99 <= e <= 1.01) sweep periapsis from about
  // -150 to +150 deg true anomaly.
  check('near-parabolic periapsis sweeps match prop2b_c (<1e-8 relative)', worst['near-parabolic'] < 1e-8);
}

console.log('='.repeat(60));
console.log('CASE 8: rvToElements vs SPICE oscltx_c');
console.log('='.repeat(60));
{
  let wE = 0, wA = 0, wAng = 0;
  for (const c of SPICE.twobody) {
    if (c.kind === 'near-parabolic') continue;   // a is ill-defined there
    const el = rvToElements(c.state0.slice(0, 3), c.state0.slice(3), c.mu);
    const ref = c.elements0;
    wE = Math.max(wE, Math.abs(el.e - ref.e));
    wA = Math.max(wA, Math.abs(el.a - ref.a) / Math.abs(ref.a));
    wAng = Math.max(wAng, angDiff(el.i, ref.i), angDiff(el.raan, ref.raan),
      angDiff(el.argp, ref.argp), angDiff(el.nu, ref.nu));
  }
  console.log(`  worst |de| = ${wE.toExponential(3)}  worst rel da = ${wA.toExponential(3)}  ` +
    `worst angle err = ${(wAng * DEG).toExponential(3)} deg`);
  check('e matches oscltx_c (<1e-10)', wE < 1e-10);
  check('a matches oscltx_c (<1e-10 relative)', wA < 1e-10);
  check('i, RAAN, argp, nu match oscltx_c (<1e-8 rad)', wAng < 1e-8);
}

console.log('='.repeat(60));
console.log('CASE 9: Lambert on the real MSL transfer (DE440 states)');
console.log('='.repeat(60));
{
  // Earth at launch (2011-11-26 15:02 UTC) and the Mars system barycentre at
  // arrival (2012-08-06 05:17 UTC), heliocentric J2000, from spkezr_c.
  const m = SPICE.msl;
  const mu = SPICE.meta.gm.sun;
  const sE = m.earth_at_launch.state, sM = m.mars_at_arrival.state;
  const rE = sE.slice(0, 3), vE = sE.slice(3), rM = sM.slice(0, 3), vM = sM.slice(3);
  const sol = lambert(rE, rM, m.tof_s, mu, true);
  check('MSL Lambert converges', sol !== null);
  if (sol) {
    const vinfDep = sol.v1.map((x, i) => x - vE[i]);
    const vinfArr = sol.v2.map((x, i) => x - vM[i]);
    const c3 = norm(vinfDep) ** 2;
    const dla = Math.asin(vinfDep[2] / norm(vinfDep)) * DEG;   // J2000 is equatorial
    const h = [rE[1] * sol.v1[2] - rE[2] * sol.v1[1], rE[2] * sol.v1[0] - rE[0] * sol.v1[2],
      rE[0] * sol.v1[1] - rE[1] * sol.v1[0]];
    // Transfer angle measured in the direction of motion: past 180 deg when
    // r1 x r2 points against the transfer's angular momentum.
    const c12 = [rE[1] * rM[2] - rE[2] * rM[1], rE[2] * rM[0] - rE[0] * rM[2], rE[0] * rM[1] - rE[1] * rM[0]];
    const acute = Math.acos((rE[0] * rM[0] + rE[1] * rM[1] + rE[2] * rM[2]) / (norm(rE) * norm(rM))) * DEG;
    const dtheta = (h[0] * c12[0] + h[1] * c12[1] + h[2] * c12[2]) >= 0 ? acute : 360 - acute;
    const endErr = vecErr(propagateRK(rE, sol.v1, m.tof_s, mu), rM) / norm(rM);
    console.log(`  tof = ${(m.tof_s / 86400).toFixed(3)} d   transfer angle = ${dtheta.toFixed(2)} deg`);
    console.log(`  C3 = ${c3.toFixed(3)} km^2/s^2   DLA = ${dla.toFixed(2)} deg   ` +
      `arrival v_inf = ${norm(vinfArr).toFixed(3)} km/s`);
    console.log(`  endpoint rel err (independent RK4) = ${endErr.toExponential(3)}`);
    check('MSL transfer reaches Mars (<1e-8 relative)', endErr < 1e-8);
    check('MSL transfer is prograde', h[2] > 0);
    check('MSL transfer is Type I (< 180 deg)', dtheta < 180);
  }
}

console.log('='.repeat(60));
console.log('CASE 10: Curtis (4th ed.) worked examples');
console.log('='.repeat(60));
{
  // Expected values: the book's worked examples, using full-precision
  // recomputes where the book rounds intermediate values (numbers from the
  // engineering-resources orrery pack, cases KEP-03..06, ELM-01..02, LAM-02).
  const mu = 398600.0;
  const D2R = 1.0 / DEG;
  const theta = (s) => { const el = rvToElements(s.r, s.v, mu); return el.nu * DEG; };

  // Ex 3.4 (KEP-03): parabola, vp = 10 km/s, 6 h after perigee.
  {
    const s = propagate([7972.0, 0.0, 0.0], [0.0, 10.0, 0.0], 21600.0, mu);
    const r = s ? norm(s.r) : NaN;
    const th = s ? Math.atan2(s.r[1], s.r[0]) * DEG : NaN;
    console.log(`  Ex 3.4  parabola:   r = ${r.toFixed(1)} km  theta = ${th.toFixed(3)} deg`);
    check('Ex 3.4 parabola r = 86,977 km (0.1%)', Math.abs(r - 86977) / 86977 < 1e-3);
    check('Ex 3.4 parabola theta = 144.754 deg (0.01)', Math.abs(th - 144.754) < 0.01);
  }
  // Ex 3.5 (KEP-04): hyperbola rp = 6678 km, vp = 15 km/s, from theta = 100 deg for 3 h.
  {
    const h = 6678.0 * 15.0, e = h * h / (mu * 6678.0) - 1.0;
    const s0 = elementsToRv({ h, e, i: 0, raan: 0, argp: 0, nu: 100 * D2R }, mu);
    const s = propagate(s0.r, s0.v, 10800.0, mu);
    const r = norm(s.r), vr = (s.r[0] * s.v[0] + s.r[1] * s.v[1]) / r, vperp = h / r;
    console.log(`  Ex 3.5  hyperbola:  r = ${r.toFixed(1)} km  theta = ${theta(s).toFixed(3)} deg  ` +
      `v_r = ${vr.toFixed(4)}  v_perp = ${vperp.toFixed(5)} km/s`);
    check('Ex 3.5 r = 163,180 km (10 km)', Math.abs(r - 163180) < 10);
    check('Ex 3.5 theta = 107.78 deg (0.01)', Math.abs(theta(s) - 107.78) < 0.01);
    // The book prints v_r = 10.496 from rounded intermediates; the exact
    // value at this theta is (mu/h) e sin(theta) = 10.4944. Check the identity
    // tightly and the book's figure to its rounding.
    const vrExact = (mu / h) * e * Math.sin(theta(s) * D2R);
    check('Ex 3.5 v_r equals (mu/h) e sin(theta) (1e-9)', Math.abs(vr - vrExact) < 1e-9);
    check('Ex 3.5 v_r = 10.496 (book, 2e-3), v_perp = 0.61386 km/s (1e-3)',
      Math.abs(vr - 10.496) < 2e-3 && Math.abs(vperp - 0.61386) < 1e-3);
  }
  // Ex 3.6 (KEP-05): hyperbola r0 = 10,000 km, v0 = 10 km/s, theta0 = 30 deg, 1 h.
  {
    const s0 = elementsToRv({ h: 95154, e: 1.4682, i: 0, raan: 0, argp: 0, nu: 30 * D2R }, mu);
    const s = propagate(s0.r, s0.v, 3600.0, mu);
    console.log(`  Ex 3.6  hyperbola:  r0 = ${norm(s0.r).toFixed(1)} km  theta = ${theta(s).toFixed(3)} deg`);
    check('Ex 3.6 theta = 100.04 deg (0.01)', Math.abs(theta(s) - 100.04) < 0.01);
  }
  // Ex 3.7 (KEP-06): r0 = [7000, -12124, 0], v0 = [2.6679, 4.6210, 0], 1 h.
  {
    const s = propagate([7000.0, -12124.0, 0.0], [2.6679, 4.6210, 0.0], 3600.0, mu);
    const er = vecErr(s.r, [-3297.77, 7413.40, 0]), ev = vecErr(s.v, [-8.2976, -0.96405, 0]);
    console.log(`  Ex 3.7  ellipse:    r = ${fmt(s.r)}  v = ${fmt(s.v)}`);
    check('Ex 3.7 r within 1.5 km, v within 2e-3 km/s', er < 1.5 && ev < 2e-3);
  }
  // Ex 4.3 (ELM-01): state vector to elements.
  {
    const el = rvToElements([-6045.0, -3490.0, 2500.0], [-3.457, 6.618, 2.533], mu);
    console.log(`  Ex 4.3  elements:   h=${el.h.toFixed(1)} e=${el.e.toFixed(6)} i=${(el.i * DEG).toFixed(3)} ` +
      `RAAN=${(el.raan * DEG).toFixed(3)} argp=${(el.argp * DEG).toFixed(4)} theta=${(el.nu * DEG).toFixed(4)}`);
    check('Ex 4.3 h within 5 km^2/s, e within 1e-4',
      Math.abs(el.h - 58311.7) < 5 && Math.abs(el.e - 0.171212) < 1e-4);
    check('Ex 4.3 i, RAAN, argp, theta within 0.05 deg',
      Math.abs(el.i * DEG - 153.249) < 0.05 && Math.abs(el.raan * DEG - 255.279) < 0.05 &&
      Math.abs(el.argp * DEG - 20.0683) < 0.05 && Math.abs(el.nu * DEG - 28.4456) < 0.05);
  }
  // Ex 4.7 (ELM-02): hyperbolic elements to state vector.
  {
    const s = elementsToRv({ h: 80000, e: 1.4, i: 30 * D2R, raan: 40 * D2R, argp: 60 * D2R, nu: 30 * D2R }, mu);
    console.log(`  Ex 4.7  state:      r = ${fmt(s.r)}  v = ${fmt(s.v)}`);
    check('Ex 4.7 r within 1 km, v within 5e-3 km/s',
      vecErr(s.r, [-4039.9, 4814.56, 3628.62]) < 1 && vecErr(s.v, [-10.386, -4.77192, 1.74388]) < 5e-3);
  }
  // Ex 5.3 (LAM-02): hyperbolic Lambert (z < 0), 5 deg apart, 13.5 h.
  {
    const r2m = 146378.0, a5 = 5 * D2R;
    const sol = lambert([273378.0, 0, 0], [r2m * Math.cos(a5), r2m * Math.sin(a5), 0], 48600.0, mu, true);
    const el = rvToElements([273378.0, 0, 0], sol.v1, mu);
    console.log(`  Ex 5.3  Lambert:    z = ${sol.z.toFixed(5)}  v1 = ${fmt(sol.v1)}  e = ${el.e.toFixed(5)}`);
    check('Ex 5.3 v1 within 1e-3 km/s', vecErr(sol.v1, [-2.4356, 0.26741, 0]) < 1e-3);
    check('Ex 5.3 e = 1.0506 (1e-4), z < 0', Math.abs(el.e - 1.0506) < 1e-4 && sol.z < 0);
  }
}

console.log('='.repeat(60));
console.log('CASE 11: propagate regressions (old element-based failures)');
console.log('='.repeat(60));
{
  const mu = 398600.4418;
  // Parabola whose e rounds to 0.9999999999999998: the old code returned a
  // confident wrong state.
  const vPar = Math.sqrt(2 * mu / 7000.0);
  const p = propagate([7000.0, 0, 0], [0, vPar, 0], 3600.0, mu);
  const pRef = propagateRK([7000.0, 0, 0], [0, vPar, 0], 3600.0, mu);
  const ePar = vecErr(p.r, pRef) / norm(pRef);
  console.log(`  near-exact parabola: rel err vs RK4 = ${ePar.toExponential(3)}`);
  check('near-exact parabola matches RK4 (<1e-8)', ePar < 1e-8);
  // Hyperbola from perigee: the old code diverged (|r| = 1.1e20 km at 1e5 s).
  const r0 = [6678.0, 0, 0], v0 = [0, 15.0, 0];
  const E0 = 112.5 - mu / 6678.0, h0 = 6678.0 * 15.0;
  let worstE = 0, worstH = 0;
  for (const dt of [1e3, 1e5, 1e6, 1e8, -1e5]) {
    const s = propagate(r0, v0, dt, mu);
    const r = norm(s.r), v = norm(s.v);
    worstE = Math.max(worstE, Math.abs((v * v / 2 - mu / r - E0) / E0));
    worstH = Math.max(worstH, Math.abs((s.r[0] * s.v[1] - s.r[1] * s.v[0] - h0) / h0));
  }
  const hRef = propagateRK(r0, v0, 1e5, mu);
  const eHyp = vecErr(propagate(r0, v0, 1e5, mu).r, hRef) / norm(hRef);
  console.log(`  hyperbola dt 1e3..1e8 s: worst rel energy err ${worstE.toExponential(2)}, ` +
    `worst rel h err ${worstH.toExponential(2)}; at 1e5 s vs RK4 ${eHyp.toExponential(3)}`);
  check('hyperbola conserves energy and h to 1e-10 up to dt = 1e8 s', worstE < 1e-10 && worstH < 1e-10);
  check('hyperbola at dt = 1e5 s matches RK4 (<1e-8)', eHyp < 1e-8);
  // Ellipse: 1000 periods plus a quarter equals a quarter period.
  const T = 2 * Math.PI * Math.sqrt(6778.0 ** 3 / mu);
  const vc = Math.sqrt(mu / 6778.0);
  const q1 = propagate([6778.0, 0, 0], [0, vc, 0], 1000.25 * T, mu);
  const q0 = propagateRK([6778.0, 0, 0], [0, vc, 0], 0.25 * T, mu);   // independent
  const eRev = vecErr(q1.r, q0);
  console.log(`  1000.25 periods vs RK4 over 0.25: difference ${eRev.toExponential(3)} km`);
  check('many-revolution propagation keeps precision (<1e-4 km vs RK4)', eRev < 1e-4);
}

console.log('='.repeat(60));
if (failures > 0) {
  console.log(`RESULT: ${failures} check(s) FAILED`);
  process.exit(1);
} else {
  console.log('RESULT: all checks PASSED');
}